mapper.select:
SELECT i.id, i.product_id, p.name AS product_name, p.category, p.price, i.current_stock, i.min_stock, i.max_stock, (i.current_stock <= i.min_stock) AS is_low_stock, i.created_at, i.updated_at FROM inventories i LEFT JOIN products p ON i.product_id = p.id
AND p.name LIKE CONCAT('%', #{productName}, '%')
AND p.category = #{category}
AND i.current_stock <= i.min_stock
ORDER BY i.updated_at DESC LIMIT #{offset}, #{limit}
